// Configuración de un pin digital de salida
const int pinLed = 13;      // Pin Digital 13 (LED integrado)
const int pinSensor = A0;   // Pin Analógico A0

void setup() {
  pinMode(pinLed, OUTPUT);
}

void loop() {
  digitalWrite(pinLed, HIGH);
  delay(1000);
  digitalWrite(pinLed, LOW);
  delay(1000);
}
